alter table public.offers add column converted_project_id uuid references public.projects(id);
create or replace function public.convert_offer_to_project(p_offer_id uuid,p_project_name text,p_domain text,p_start_date date,p_owner_id uuid,p_is_white_label boolean default false)returns uuid language plpgsql security invoker set search_path=''as $$
declare source_offer public.offers%rowtype;source_revision public.offer_revisions%rowtype;new_project uuid;line record;new_project_service uuid;service_period public.service_periodicity;
begin if not public.has_permission('projects.manage')or not public.has_permission('sales.manage')or not public.has_permission('finance.manage')then raise exception'insufficient_permission'using errcode='42501';end if;select*into source_offer from public.offers where id=p_offer_id for update;if source_offer.id is null then raise exception'offer_not_found';end if;if source_offer.converted_project_id is not null then return source_offer.converted_project_id;end if;if source_offer.client_id is null then raise exception'offer_must_belong_to_client';end if;if source_offer.status<>'accepted'then raise exception'offer_must_be_accepted';end if;select*into source_revision from public.offer_revisions where offer_id=p_offer_id and revision_number=source_offer.current_revision;
 insert into public.projects(client_id,name,domain,owner_id,start_date,status,is_white_label,created_by,updated_by)values(source_offer.client_id,p_project_name,nullif(p_domain,''),p_owner_id,p_start_date,'active',p_is_white_label,auth.uid(),auth.uid())returning id into new_project;
 for line in select i.*,s.default_periodicity from public.offer_revision_items i join public.services s on s.id=i.service_id where i.revision_id=source_revision.id and i.service_id is not null loop service_period:=line.default_periodicity;insert into public.project_services(project_id,service_id,periodicity,currency,billing_preference,start_date,status,created_by,updated_by)values(new_project,line.service_id,service_period,source_offer.currency,'invoiced',p_start_date,'active',auth.uid(),auth.uid())returning id into new_project_service;insert into public.project_service_prices(project_service_id,net_price,vat_rate,currency,effective_from,created_by)values(new_project_service,line.line_net,line.vat_rate,source_offer.currency,p_start_date,auth.uid());end loop;
 update public.offers set converted_project_id=new_project,updated_by=auth.uid()where id=p_offer_id;return new_project;end$$;
grant execute on function public.convert_offer_to_project(uuid,text,text,date,uuid,boolean)to authenticated;
